export default function read({ body }) {
  const e = JSON.parse(body.event),
    taskId = e["ClickUp ID"],
    name = e["Task name"],
    status = e.Status,
    dueDate = Date.parse(e.Deadline?.start);
  if (!taskId || !name || !status || !Number.isFinite(dueDate))
    throw Error("Notion page requires ClickUp ID, task name, status and deadline");
  return { taskId, name, status, dueDate };
}

