export default function read({ body }) {
  const e = JSON.parse(body.event),
    taskId = e.task_id,
    status = e.history_items?.[0]?.after?.status;
  if (!taskId || !status) throw Error("ClickUp status event requires task ID and status");
  return { filter: { property: "ClickUp ID", rich_text: { equals: taskId } }, status };
}

