export default function collect({ previous, response }) {
  const s = previous ?? { pages: [], started: false };
  if (s.started) {
    if (!Array.isArray(response?.results)) throw Error("Notion query returned no results");
    s.pages.push(...response.results);
    if (response.has_more && !response.next_cursor) throw Error("Notion query returned no cursor");
    if (!response.has_more) return { state: s, more: false, cursor: null, pages: s.pages };
  }
  return {
    state: { pages: s.pages, started: true },
    more: true,
    cursor: s.started ? response.next_cursor : null,
    pages: s.pages,
  };
}

