export default function next({ pages, index, status }) {
  let i = index ?? 0;
  while (i < pages.length && pages[i]?.properties?.Status?.select?.name === status) i++;
  return {
    has: i < pages.length,
    pageId: i < pages.length ? pages[i].id : "NO_PAGE",
    nextIndex: i + 1,
    properties: { Status: { select: { name: status } } },
  };
}
